def prevPermOpt1(arr: list[int]) -> list[int]:
    n = len(arr)
    idx = -1
    for i in range(n - 2, -1, -1):
        if arr[i] > arr[i + 1]:
            idx = i
            break
    if idx == -1: return arr
    # Find largest arr[j] < arr[idx] to the right (smallest index for ties)
    best_j = idx + 1
    for j in range(idx + 1, n):
        if arr[j] < arr[idx] and arr[j] > arr[best_j]:
            best_j = j
    arr[idx], arr[best_j] = arr[best_j], arr[idx]
    return arr

